import time
import numpy as np
import random

DIMENSIONS = [3, 4, 7]

def construct():
    """
    Constructs a rank-minimal exact tensor decomposition for multiplying 
    a 3 by 4 matrix by a 4 by 7 matrix.
    
    Uses a search strategy to find a rank lower than the schoolbook rank (84).
    """
    n, m, p = DIMENSIONS
    schoolbook_rank = n * m * p
    
    # Target tensor T of shape (n*m, m*p, p*n)
    # T[i*m+j, j*p+k, k*n+i] = 1
    # We want U (n*m, r), V (m*p, r), W (p*n, r) such that 
    # sum_l U[:, l] V[:, l]^T ... no, tensor product.
    # The tensor generated by U, V, W is T_gen where 
    # T_gen[a, b, c] = sum_l U[a, l] V[b, l] W[c, l]
    # We need T_gen == T_target.
    
    T_target = np.zeros((n*m, m*p, p*n))
    for i in range(n):
        for j in range(m):
            for k in range(p):
                T_target[i*m+j, j*p+k, k*n+i] = 1.0

    start_time = time.time()
    deadline = start_time + 145.0
    
    best_rank = schoolbook_rank
    best_U = None
    best_V = None
    best_W = None
    
    # Schoolbook solution
    U_school = np.zeros((n*m, schoolbook_rank))
    V_school = np.zeros((m*p, schoolbook_rank))
    W_school = np.zeros((p*n, schoolbook_rank))
    col = 0
    for i in range(n):
        for j in range(m):
            for k in range(p):
                U_school[i*m+j, col] = 1.0
                V_school[j*p+k, col] = 1.0
                W_school[k*n+i, col] = 1.0
                col += 1
    best_U = U_school
    best_V = V_school
    best_W = W_school

    # Search for lower ranks
    # Try ranks from schoolbook_rank - 1 down to a lower bound
    # Lower bound estimate: n*m*p / 2 ?
    
    for r in range(schoolbook_rank - 1, 20, -1):
        if time.time() > deadline - 10:
            break
            
        # Try a few random restarts for this rank
        max_restarts = 5
        found = False
        for restart in range(max_restarts):
            if time.time() > deadline - 10:
                break
                
            # Random initialization
            U = np.random.randn(n*m, r)
            V = np.random.randn(m*p, r)
            W = np.random.randn(p*n, r)
            
            # Simple gradient descent or iterative refinement
            # Minimize || T_gen - T_target ||_F
            # This is a non-convex problem.
            # We can use a simple alternating least squares (ALS) approach.
            # Fix U, V, solve for W.
            # Fix U, W, solve for V.
            # Fix V, W, solve for U.
            
            for step in range(100):
                if time.time() > deadline - 10:
                    break
                    
                # Solve for W
                # T_gen[a,b,c] = sum_l U[a,l] V[b,l] W[c,l]
                # For each c, W[c,:] is a vector.
                # We want to minimize sum_{a,b} (sum_l U[a,l] V[b,l] W[c,l] - T_target[a,b,c])^2
                # This is a linear least squares problem for W[c,:].
                # Let M_c be the matrix where M_c[a,b] = sum_l U[a,l] V[b,l] ? No.
                # The term is sum_l (U[a,l] V[b,l]) W[c,l].
                # Let X_c be a matrix of size (n*m * m*p) x r.
                # X_c[a,b, l] = U[a,l] V[b,l].
                # Then we want to minimize || X_c W[c,:] - T_target[:,:,c] ||^2.
                # T_target[:,:,c] is a vector of size n*m * m*p.
                
                # Construct X_c
                # This might be expensive.
                # n*m = 12, m*p = 28.
                # X_c size: 12*28 x r.
                # r is up to 83.
                # 336 x 83.
                
                # Actually, we can reshape.
                # U is (12, r), V is (28, r).
                # Outer product U V^T is (12, 28, r)? No.
                # We need the matrix X_c where row index is (a,b) and col index is l.
                # X_c[(a,b), l] = U[a,l] V[b,l].
                
                # We can compute this as:
                # U_V = np.einsum('al,bl->abl', U, V) # (12, 28, r)
                # X_c = U_V.reshape(12*28, r)
                
                U_V = np.einsum('al,bl->abl', U, V)
                X = U_V.reshape(n*m * m*p, r)
                
                # T_target_c is T_target[:, :, c] reshaped to (n*m*m*p, 1)
                # We solve X w = t
                # w = np.linalg.lstsq(X, T_target.reshape(-1, 1), rcond=None)[0]
                # But we need W[c,:] for all c.
                # We can do this for all c at once?
                # The X matrix depends on c? No, X is the same for all c?
                # X[(a,b), l] = U[a,l] V[b,l]. This does not depend on c.
                # So X is constant for all c.
                # We want to find W (p*n, r) such that for each c:
                # X W[c,:]^T = T_target[:, :, c].reshape(-1)
                
                # So we have a system: X W^T = T_target_reshaped
                # T_target_reshaped is (p*n, n*m*m*p)?
                # T_target is (n*m, m*p, p*n).
                # We want to solve for W (p*n, r).
                # Let Y be the matrix where Y[c, (a,b)] = T_target[a,b,c].
                # Y shape: (p*n, n*m*m*p).
                # We want X^T W^T = Y?
                # X is (n*m*m*p, r).
                # W is (p*n, r).
                # X W^T is (n*m*m*p, p*n).
                # We want X W^T = Y^T.
                
                Y = T_target.transpose(2, 0, 1).reshape(p*n, n*m*m*p)
                # Solve X W^T = Y^T
                # W^T = X^+ Y^T
                # W = (X^+ Y^T)^T = Y X^+^T
                
                # Use lstsq
                # Minimize || X W^T - Y^T ||_F
                # This is equivalent to minimizing || W X^T - Y ||_F
                # We can solve for W directly.
                # Let's use np.linalg.lstsq on the transposed system.
                # X^T W^T = Y^T
                # W^T = np.linalg.lstsq(X.T, Y.T, rcond=None)[0]
                
                try:
                    W_new = np.linalg.lstsq(X.T, Y.T, rcond=None)[0].T
                except:
                    break
                
                W = W_new
                
                # Solve for V
                # Fix U, W.
                # T_gen[a,b,c] = sum_l U[a,l] V[b,l] W[c,l]
                # For each b, V[b,:] is a vector.
                # Minimize sum_{a,c} (sum_l U[a,l] W[c,l] V[b,l] - T_target[a,b,c])^2
                # Let Z_b be a matrix of size (n*m * p*n) x r.
                # Z_b[(a,c), l] = U[a,l] W[c,l].
                # Z_b is constant for all b? No, Z_b depends on b?
                # Z_b[(a,c), l] = U[a,l] W[c,l]. This does not depend on b.
                # So Z is constant for all b.
                # We want Z V[b,:]^T = T_target[:, b, :].reshape(-1)
                
                U_W = np.einsum('al,cl->acl', U, W)
                Z = U_W.reshape(n*m * p*n, r)
                
                # T_target_b is T_target[:, b, :] reshaped to (n*m*p*n, 1)
                # Y_V is (m*p, n*m*p*n)
                Y_V = T_target.transpose(1, 0, 2).reshape(m*p, n*m*p*n)
                
                try:
                    V_new = np.linalg.lstsq(Z.T, Y_V.T, rcond=None)[0].T
                except:
                    break
                
                V = V_new
                
                # Solve for U
                # Fix V, W.
                # T_gen[a,b,c] = sum_l U[a,l] V[b,l] W[c,l]
                # For each a, U[a,:] is a vector.
                # Minimize sum_{b,c} (sum_l V[b,l] W[c,l] U[a,l] - T_target[a,b,c])^2
                # Let Q_a be a matrix of size (m*p * p*n) x r.
                # Q_a[(b,c), l] = V[b,l] W[c,l].
                # Q is constant for all a.
                
                V_W = np.einsum('bl,cl->bcl', V, W)
                Q = V_W.reshape(m*p * p*n, r)
                
                Y_U = T_target.transpose(0, 1, 2).reshape(n*m, m*p*p*n)
                
                try:
                    U_new = np.linalg.lstsq(Q.T, Y_U.T, rcond=None)[0].T
                except:
                    break
                
                U = U_new
            
            # Check error
            # Compute T_gen
            T_gen = np.einsum('al,bl,cl->abc', U, V, W)
            error = np.linalg.norm(T_gen - T_target)
            
            if error < 1e-5:
                # Snap to integers/half-integers
                U_snap = np.round(U * 2) / 2
                V_snap = np.round(V * 2) / 2
                W_snap = np.round(W * 2) / 2
                
                T_gen_snap = np.einsum('al,bl,cl->abc', U_snap, V_snap, W_snap)
                error_snap = np.linalg.norm(T_gen_snap - T_target)
                
                if error_snap < 1e-9:
                    best_rank = r
                    best_U = U_snap
                    best_V = V_snap
                    best_W = W_snap
                    found = True
                    break # Break restart loop, try lower rank
        
        if found:
            # We found a solution for this rank, try lower
            continue
        else:
            # If we failed for this rank, we might fail for lower ranks too?
            # Not necessarily, but usually if a rank is too low, it's infeasible.
            # We can stop if we fail for several consecutive ranks.
            # For now, just continue to next lower rank.
            pass

    # Convert to lists
    return {
        "U": best_U.tolist(),
        "V": best_V.tolist(),
        "W": best_W.tolist()
    }
